        journeyDescription: { type: "string", description: "User journey text. Without connections, triggers scan mode \u2014 returns interactive element inventory for AI to plan wiring." },
        frameIds: { type: "array", items: { type: "string" }, description: "Frames to scan/wire (omit for auto-discover)." },
